1	package custody
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Store 是一份本地样品数据的入口。零值不可用，请通过 Open 创建或重新打开。
15	//
16	// 同一时刻所有读写操作都由一把互斥锁串行化，因此并发操作同一样品时，
17	// 既不会超量分装，也不会出现两条待确认交接。每次成功的写操作都会
18	// 原子落盘（临时文件 + rename），关闭后重新打开同一文件即可恢复
19	// 全部样品、保管历史以及交接编号的重复提交判断。
20	type Store struct {
21		path string
22		mu   sync.Mutex
23		data *ledger
24	
25		// now 可在同包测试中替换，便于确定性地控制事件时间。
26		now func() time.Time
27	}
28	
29	// Open 打开 path 指向的本地样品数据：文件不存在时创建一份新数据，
30	// 已存在时原样重新打开，历史记录与交接编号判断继续有效。
31	func Open(path string) (*Store, error) {
32		if strings.TrimSpace(path) == "" {
33			return nil, fmt.Errorf("%w: 数据文件路径不能为空", ErrInvalid)
34		}
35	
36		s := &Store{path: path, now: time.Now}
37	
38		raw, err := os.ReadFile(path)
39		switch {
40		case err == nil:
41			var l ledger
42			if err := json.Unmarshal(raw, &l); err != nil {
43				return nil, fmt.Errorf("读取本地样品数据 %s 失败: %w", path, err)
44			}
45			if l.Version != 1 {
46				return nil, fmt.Errorf("本地样品数据 %s 的版本 %d 不受支持", path, l.Version)
47			}
48			if l.Samples == nil {
49				l.Samples = make(map[string]*sampleRecord)
50			}
51			if l.Transfers == nil {
52				l.Transfers = make(map[string]*transferRecord)
53			}
54			if err := validateRestored(&l); err != nil {
55				return nil, err
56			}
57			s.data = &l
58		case os.IsNotExist(err):
59			s.data = newLedger()
60			if err := s.persist(s.data); err != nil {
61				return nil, err
62			}
63		default:
64			return nil, fmt.Errorf("打开本地样品数据 %s 失败: %w", path, err)
65		}
66		return s, nil
67	}
68	
69	// validateRestored 校验从文件恢复的数据中待确认交接关联是否一致。
70	// 样品的非空 pendingId 必须指向一条实际存在、尚未确认、且属于该样品的
71	// 交接；每条尚未确认的交接也必须对应一份实际存在、且 pendingId 正好指向
72	// 它的样品。待确认交接表示样品当前全部剩余量尚待指定人员接收，因此其
73	// 内容还必须与样品当前记录一致：样品未销毁、剩余量大于零、交出人等于
74	// 当前持有人、交出地点等于当前地点、交接量精确等于当前剩余量。已确认
75	// 交接属于保留的历史，不要求样品继续指向它，也不核对其与样品当前
76	// 持有人、地点或剩余量的差异。集合中占用编号却为 null 的条目视为
77	// 损坏，不能当作记录不存在。任一问题都使整个文件无法恢复，绝不只
78	// 加载其中一部分，也不改动原文件。
79	func validateRestored(l *ledger) error {
80		sampleIDs := make([]string, 0, len(l.Samples))
81		for id := range l.Samples {
82			sampleIDs = append(sampleIDs, id)
83		}
84		sort.Strings(sampleIDs)
85		for _, id := range sampleIDs {
86			rec := l.Samples[id]
87			if rec == nil {
88				return fmt.Errorf("%w: 样品编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
89			}
90			if rec.PendingID == "" {
91				continue
92			}
93			tr, ok := l.Transfers[rec.PendingID]
94			switch {
95			case !ok:
96				return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接不存在，无法恢复",
97					ErrInvalid, id, rec.PendingID)
98			case tr == nil:
99				return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接记录为 null，无法恢复",
100					ErrInvalid, id, rec.PendingID)
101			case tr.Confirmed:
102				return fmt.Errorf("%w: 样品 %q 记着的交接 %q 已确认，不能仍是待确认，无法恢复",
103					ErrInvalid, id, rec.PendingID)
104			case tr.SampleID != id:
105				return fmt.Errorf("%w: 样品 %q 记着的待确认交接 %q 属于样品 %q，无法恢复",
106					ErrInvalid, id, rec.PendingID, tr.SampleID)
107			}
108			if err := validatePendingContent(id, rec, tr); err != nil {
109				return err
110			}
111		}
112	
113		transferIDs := make([]string, 0, len(l.Transfers))
114		for id := range l.Transfers {
115			transferIDs = append(transferIDs, id)
116		}
117		sort.Strings(transferIDs)
118		for _, id := range transferIDs {
119			rec := l.Transfers[id]
120			if rec == nil {
121				return fmt.Errorf("%w: 交接编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
122			}
123			if rec.Confirmed {
124				continue
125			}
126			sample, ok := l.Samples[rec.SampleID]
127			switch {
128			case !ok:
129				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 不存在，无法恢复",
130					ErrInvalid, id, rec.SampleID)
131			case sample == nil:
132				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 记录为 null，无法恢复",
133					ErrInvalid, id, rec.SampleID)
134			case sample.PendingID != id:
135				return fmt.Errorf("%w: 待确认交接 %q 的样品 %q 并未记着该交接编号，无法恢复",
136					ErrInvalid, id, rec.SampleID)
137			default:
138				if err := validatePendingContent(rec.SampleID, sample, rec); err != nil {
139					return err
140				}
141			}
142		}
143		return nil
144	}
145	
146	// validatePendingContent 核对一条待确认交接的内容是否与样品当前记录一致。
147	// 待确认交接表示样品当前全部剩余量尚待指定人员接收：样品必须未销毁且
148	// 剩余量大于零，交接的交出人、交出地点和交接量必须分别精确等于样品的
149	// 当前持有人、当前地点和当前剩余量。任一不符都返回包装了 ErrInvalid 的
150	// 错误，并在信息中写明样品编号、交接编号以及冲突项（人员、地点、数量
151	// 或销毁状态）；数量冲突同时列出双方数量，统一按三位小数毫升展示。
152	func validatePendingContent(sampleID string, sample *sampleRecord, tr *transferRecord) error {
153		switch {
154		case sample.Destroyed != nil:
155			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品已销毁，无法恢复",
156				ErrInvalid, sampleID, tr.ID)
157		case sample.Remaining <= 0:
158			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品当前剩余量为 %s 毫升（未销毁），无法恢复",
159				ErrInvalid, sampleID, tr.ID, formatUnits(sample.Remaining))
160		case tr.FromHolder != sample.Holder:
161			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出人 %q 与样品当前持有人 %q 不一致，无法恢复",
162				ErrInvalid, sampleID, tr.ID, tr.FromHolder, sample.Holder)
163		case tr.FromLocation != sample.Location:
164			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出地点 %q 与样品当前地点 %q 不一致，无法恢复",
165				ErrInvalid, sampleID, tr.ID, tr.FromLocation, sample.Location)
166		case tr.Qty != sample.Remaining:
167			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交接量 %s 毫升与样品当前剩余量 %s 毫升不一致，无法恢复",
168				ErrInvalid, sampleID, tr.ID, formatUnits(tr.Qty), formatUnits(sample.Remaining))
169		}
170		return nil
171	}
172	
173	// persist 把整份状态原子写入文件：先写同目录临时文件，再 rename 覆盖，
174	// 避免进程中断留下半截数据。
175	func (s *Store) persist(l *ledger) error {
176		raw, err := json.MarshalIndent(l, "", "  ")
177		if err != nil {
178			return fmt.Errorf("编码本地样品数据失败: %w", err)
179		}
180	
181		dir := filepath.Dir(s.path)
182		tmp, err := os.CreateTemp(dir, ".custody-*.tmp")
183		if err != nil {
184			return fmt.Errorf("创建临时数据文件失败: %w", err)
185		}
186		tmpName := tmp.Name()
187		defer os.Remove(tmpName)
188	
189		if _, err := tmp.Write(raw); err != nil {
190			tmp.Close()
191			return fmt.Errorf("写入临时数据文件失败: %w", err)
192		}
193		if err := tmp.Close(); err != nil {
194			return fmt.Errorf("关闭临时数据文件失败: %w", err)
195		}
196		if err := os.Rename(tmpName, s.path); err != nil {
197			return fmt.Errorf("替换本地样品数据文件失败: %w", err)
198		}
199		return nil
200	}
201	
202	// commit 在候选状态上落盘并替换内存状态。调用方必须保证 candidate
203	// 已通过全部校验；落盘失败时内存状态保持不变。
204	func (s *Store) commit(candidate *ledger) error {
205		if err := s.persist(candidate); err != nil {
206			return err
207		}
208		s.data = candidate
209		return nil
210	}
211	
212	// RegisterInput 是登记原样的入参。
213	type RegisterInput struct {
214		// ID 为样品编号，在这份数据内唯一，去空白后非空。
215		ID string
216		// Qty 为初始数量（毫升），大于零、最多三位小数的十进制字符串。
217		Qty string
218		// Holder 为初始持有人，去空白后非空。
219		Holder string
220		// Location 为初始地点，去空白后非空。
221		Location string
222	}
223	
224	// Register 登记一份原样。编号重复等冲突返回包装了 ErrConflict 的错误，
225	// 且不会写入任何记录。
226	func (s *Store) Register(in RegisterInput) (*Sample, error) {
227		s.mu.Lock()
228		defer s.mu.Unlock()
229	
230		id, err := trimRequired("样品编号", in.ID)
231		if err != nil {
232			return nil, err
233		}
234		holder, err := trimRequired("持有人", in.Holder)
235		if err != nil {
236			return nil, err
237		}
238		location, err := trimRequired("地点", in.Location)
239		if err != nil {
240			return nil, err
241		}
242		qty, err := parseQuantity(in.Qty)
243		if err != nil {
244			return nil, err
245		}
246		if _, exists := s.data.Samples[id]; exists {
247			return nil, fmt.Errorf("%w: 样品编号 %q 已存在", ErrConflict, id)
248		}
249	
250		candidate := s.data.deepCopy()
251		now := s.now().UTC()
252		candidate.Samples[id] = &sampleRecord{
253			ID:        id,
254			Initial:   qty,
255			Remaining: qty,
256			Holder:    holder,
257			Location:  location,
258			Children:  []string{},
259			History: []historyRecord{{
260				Kind:     "register",
261				Time:     now,
262				Holder:   holder,
263				Location: location,
264				Detail:   "登记原样",
265			}},
266		}
267		if err := s.commit(candidate); err != nil {
268			return nil, err
269		}
270		return buildSampleView(candidate.Samples[id], candidate), nil
271	}
272	
273	// SplitPart 是一次分装中的一个子样。
274	type SplitPart struct {
275		// ID 为子样编号，在这份数据内唯一，去空白后非空。
276		ID string
277		// Qty 为该子样数量（毫升），大于零、最多三位小数。
278		Qty string
279	}
280	
281	// SplitInput 是一次分装的入参；一次分装可以同时创建多个子样。
282	type SplitInput struct {
283		// ParentID 为来源样品编号。
284		ParentID string
285		// Parts 为本次要创建的全部子样，至少一个。
286		Parts []SplitPart
287	}
288	
289	// Split 执行一次原子分装。任一子样编号重复、数量不合法或子样总量超过
290	// 来源样品剩余量时，整次分装都不生效。成功后来源样品按整数刻度精确
291	// 扣减，子样继承当时的持有人和地点，并可继续分装。
292	//
293	// 返回来源样品的最新视图；子样可通过 GetSample 分别查询。
294	func (s *Store) Split(in SplitInput) (*Sample, error) {
295		s.mu.Lock()
296		defer s.mu.Unlock()
297	
298		parentID, err := trimRequired("来源样品编号", in.ParentID)
299		if err != nil {
300			return nil, err
301		}
302		if len(in.Parts) == 0 {
303			return nil, fmt.Errorf("%w: 一次分装至少要创建一个子样", ErrInvalid)
304		}
305	
306		parent, ok := s.data.Samples[parentID]
307		if !ok {
308			return nil, fmt.Errorf("%w: 来源样品 %q 不存在", ErrNotFound, parentID)
309		}
310	
311		// 先在局部完成全部校验，任何一项不通过都直接返回，不动状态。
312		type parsedPart struct {
313			id  string
314			qty int64
315		}
316		parsed := make([]parsedPart, 0, len(in.Parts))
317		seen := make(map[string]struct{}, len(in.Parts))
318		var total int64
319		for _, p := range in.Parts {
320			id, err := trimRequired("子样编号", p.ID)
321			if err != nil {
322				return nil, err
323			}
324			if _, dup := seen[id]; dup {
325				return nil, fmt.Errorf("%w: 本次分装中子样编号 %q 重复", ErrInvalid, id)
326			}
327			if _, exists := s.data.Samples[id]; exists {
328				return nil, fmt.Errorf("%w: 子样编号 %q 已存在", ErrConflict, id)
329			}
330			if id == parentID {
331				return nil, fmt.Errorf("%w: 子样编号 %q 不能与来源样品相同", ErrInvalid, id)
332			}
333			qty, err := parseQuantity(p.Qty)
334			if err != nil {
335				return nil, err
336			}
337			seen[id] = struct{}{}
338			parsed = append(parsed, parsedPart{id: id, qty: qty})
339			total += qty
340			if total < 0 {
341				return nil, fmt.Errorf("%w: 子样总量超出可表示范围", ErrInvalid)
342			}
343		}
344	
345		if parent.Destroyed != nil {
346			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能再分装", ErrConflict, parentID)
347		}
348		if parent.PendingID != "" {
349			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能分装",
350				ErrConflict, parentID, parent.PendingID)
351		}
352		if parent.Remaining == 0 {
353			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能再分装", ErrConflict, parentID)
354		}
355		if total > parent.Remaining {
356			return nil, fmt.Errorf("%w: 子样总量 %s 毫升超过样品 %q 的剩余量 %s 毫升",
357				ErrConflict, formatUnits(total), parentID, formatUnits(parent.Remaining))
358		}
359	
360		candidate := s.data.deepCopy()
361		cpParent := candidate.Samples[parentID]
362		now := s.now().UTC()
363	
364		childIDs := make([]string, 0, len(parsed))
365		for _, p := range parsed {
366			childIDs = append(childIDs, p.id)
367			candidate.Samples[p.id] = &sampleRecord{
368				ID:        p.id,
369				ParentID:  parentID,
370				Initial:   p.qty,
371				Remaining: p.qty,
372				Holder:    cpParent.Holder,
373				Location:  cpParent.Location,
374				Children:  []string{},
375				History: []historyRecord{{
376					Kind:     "split",
377					Time:     now,
378					Holder:   cpParent.Holder,
379					Location: cpParent.Location,
380					Detail:   fmt.Sprintf("由样品 %s 分装", parentID),
381				}},
382			}
383		}
384		cpParent.Remaining -= total
385		cpParent.Children = append(cpParent.Children, childIDs...)
386		cpParent.History = append(cpParent.History, historyRecord{
387			Kind:     "split",
388			Time:     now,
389			Holder:   cpParent.Holder,
390			Location: cpParent.Location,
391			Detail:   fmt.Sprintf("分装创建子样 %s", strings.Join(childIDs, ", ")),
392		})
393	
394		if err := s.commit(candidate); err != nil {
395			return nil, err
396		}
397		return buildSampleView(cpParent, candidate), nil
398	}
399	
400	// HandoverInput 是发起交接（交出）的入参。
401	type HandoverInput struct {
402		// TransferID 为本次交接编号，在本地数据中唯一，去空白后非空。
403		TransferID string
404		// SampleID 为要交出的样品编号。
405		SampleID string
406		// FromHolder 为交出人，必须与样品当前持有人完全一致（比较前对入参去空白）。
407		FromHolder string
408		// FromLocation 为交出地点，必须与样品当前地点完全一致。
409		FromLocation string
410		// ToHolder 为指定接收人，不能与交出人相同。
411		ToHolder string
412		// ToLocation 为目的地点。
413		ToLocation string
414		// HandedOverAt 为交出时间。
415		HandedOverAt time.Time
416	}
417	
418	// Handover 发起一次交接：转移该样品的全部剩余量，交接进入待确认状态，
419	// 原持有人和地点保持不变，直到指定接收人在目的地点确认。
420	//
421	// 交接编号已存在时：内容（样品、人员、地点、时间）完全一致则原样返回
422	// 既有交接（无论是否已确认）；任一内容不同则拒绝。
423	func (s *Store) Handover(in HandoverInput) (*TransferView, error) {
424		s.mu.Lock()
425		defer s.mu.Unlock()
426	
427		transferID, err := trimRequired("交接编号", in.TransferID)
428		if err != nil {
429			return nil, err
430		}
431		sampleID, err := trimRequired("样品编号", in.SampleID)
432		if err != nil {
433			return nil, err
434		}
435		fromHolder, err := trimRequired("交出人", in.FromHolder)
436		if err != nil {
437			return nil, err
438		}
439		fromLocation, err := trimRequired("交出地点", in.FromLocation)
440		if err != nil {
441			return nil, err
442		}
443		toHolder, err := trimRequired("接收人", in.ToHolder)
444		if err != nil {
445			return nil, err
446		}
447		toLocation, err := trimRequired("目的地点", in.ToLocation)
448		if err != nil {
449			return nil, err
450		}
451		if in.HandedOverAt.IsZero() {
452			return nil, fmt.Errorf("%w: 交出时间不能为空", ErrInvalid)
453		}
454		handedAt := in.HandedOverAt.UTC()
455	
456		if existing, ok := s.data.Transfers[transferID]; ok {
457			if !sameHandoverRequest(existing, sampleID, fromHolder, fromLocation, toHolder, toLocation, handedAt) {
458				return nil, fmt.Errorf("%w: 交接编号 %q 已被内容不同的交接使用", ErrConflict, transferID)
459			}
460			// 完全相同的重复提交：返回原交接，不增加任何记录。
461			return buildTransferView(existing), nil
462		}
463	
464		sample, ok := s.data.Samples[sampleID]
465		if !ok {
466			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
467		}
468		if sample.Destroyed != nil {
469			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能发起新的交接", ErrConflict, sampleID)
470		}
471		if sample.Remaining == 0 {
472			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能发起交接", ErrConflict, sampleID)
473		}
474		if sample.PendingID != "" {
475			return nil, fmt.Errorf("%w: 样品 %q 已存在待确认交接 %s",
476				ErrConflict, sampleID, sample.PendingID)
477		}
478		if sample.Holder != fromHolder {
479			return nil, fmt.Errorf("%w: 交出人 %q 与样品 %q 当前持有人 %q 不一致",
480				ErrInvalid, fromHolder, sampleID, sample.Holder)
481		}
482		if sample.Location != fromLocation {
483			return nil, fmt.Errorf("%w: 交出地点 %q 与样品 %q 当前地点 %q 不一致",
484				ErrInvalid, fromLocation, sampleID, sample.Location)
485		}
486		if toHolder == fromHolder {
487			return nil, fmt.Errorf("%w: 接收人不能与交出人 %q 相同", ErrInvalid, fromHolder)
488		}
489	
490		candidate := s.data.deepCopy()
491		rec := &transferRecord{
492			ID:           transferID,
493			SampleID:     sampleID,
494			FromHolder:   fromHolder,
495			FromLocation: fromLocation,
496			ToHolder:     toHolder,
497			ToLocation:   toLocation,
498			Qty:          sample.Remaining,
499			HandedOverAt: handedAt,
500		}
501		candidate.Transfers[transferID] = rec
502		cpSample := candidate.Samples[sampleID]
503		cpSample.PendingID = transferID
504		cpSample.History = append(cpSample.History, historyRecord{
505			Kind:     "transfer-out",
506			Time:     handedAt,
507			Holder:   fromHolder,
508			Location: fromLocation,
509			Detail:   fmt.Sprintf("发起交接 %s，待 %s 在 %s 接收", transferID, toHolder, toLocation),
510		})
511	
512		if err := s.commit(candidate); err != nil {
513			return nil, err
514		}
515		return buildTransferView(rec), nil
516	}
517	
518	// sameHandoverRequest 判断已存交接与本次请求的内容是否完全相同。
519	func sameHandoverRequest(t *transferRecord, sampleID, fromHolder, fromLocation, toHolder, toLocation string, handedAt time.Time) bool {
520		return t.SampleID == sampleID &&
521			t.FromHolder == fromHolder &&
522			t.FromLocation == fromLocation &&
523			t.ToHolder == toHolder &&
524			t.ToLocation == toLocation &&
525			t.HandedOverAt.Equal(handedAt)
526	}
527	
528	// ConfirmInput 是确认接收的入参。
529	type ConfirmInput struct {
530		// TransferID 为待确认的交接编号。
531		TransferID string
532		// Receiver 为实际接收人，必须是发起时指定的接收人。
533		Receiver string
534		// AtLocation 为接收地点，必须是发起时的目的地点。
535		AtLocation string
536		// ReceivedAt 为接收时间，不能早于交出时间。
537		ReceivedAt time.Time
538	}
539	
540	// Confirm 由指定接收人在目的地点确认接收。确认后样品的持有人和地点
541	// 才真正改变，待确认状态结束。
542	//
543	// 对已确认交接重复提交完全相同的接收信息（接收人、地点、时间）时，
544	// 返回原结果且不增加转手记录；信息不同则拒绝。
545	func (s *Store) Confirm(in ConfirmInput) (*TransferView, error) {
546		s.mu.Lock()
547		defer s.mu.Unlock()
548	
549		transferID, err := trimRequired("交接编号", in.TransferID)
550		if err != nil {
551			return nil, err
552		}
553		receiver, err := trimRequired("接收人", in.Receiver)
554		if err != nil {
555			return nil, err
556		}
557		atLocation, err := trimRequired("接收地点", in.AtLocation)
558		if err != nil {
559			return nil, err
560		}
561		if in.ReceivedAt.IsZero() {
562			return nil, fmt.Errorf("%w: 接收时间不能为空", ErrInvalid)
563		}
564		receivedAt := in.ReceivedAt.UTC()
565	
566		rec, ok := s.data.Transfers[transferID]
567		if !ok {
568			// 明确的不存在错误，绝不顺带创建交接。
569			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
570		}
571	
572		if rec.Confirmed {
573			same := rec.ConfirmedBy == receiver &&
574				rec.ToLocation == atLocation &&
575				rec.ReceivedAt != nil && rec.ReceivedAt.Equal(receivedAt)
576			if !same {
577				return nil, fmt.Errorf("%w: 交接 %q 已确认，接收信息与原确认不一致", ErrConflict, transferID)
578			}
579			return buildTransferView(rec), nil
580		}
581	
582		if receiver != rec.ToHolder {
583			return nil, fmt.Errorf("%w: 只有指定接收人 %q 能确认交接 %q，实际确认人为 %q",
584				ErrConflict, rec.ToHolder, transferID, receiver)
585		}
586		if atLocation != rec.ToLocation {
587			return nil, fmt.Errorf("%w: 必须在目的地点 %q 确认交接 %q，实际地点为 %q",
588				ErrConflict, rec.ToLocation, transferID, atLocation)
589		}
590		if receivedAt.Before(rec.HandedOverAt) {
591			return nil, fmt.Errorf("%w: 接收时间不能早于交出时间 %s",
592				ErrInvalid, rec.HandedOverAt.Format(time.RFC3339))
593		}
594	
595		candidate := s.data.deepCopy()
596		cp := candidate.Transfers[transferID]
597		cp.Confirmed = true
598		cp.ConfirmedBy = receiver
599		receivedAtCopy := receivedAt
600		cp.ReceivedAt = &receivedAtCopy
601	
602		sample := candidate.Samples[cp.SampleID]
603		sample.Holder = receiver
604		sample.Location = atLocation
605		sample.PendingID = ""
606		sample.History = append(sample.History, historyRecord{
607			Kind:     "transfer-in",
608			Time:     receivedAt,
609			Holder:   receiver,
610			Location: atLocation,
611			Detail:   fmt.Sprintf("交接 %s 确认接收（交出时间 %s）", transferID, cp.HandedOverAt.Format(time.RFC3339)),
612		})
613	
614		if err := s.commit(candidate); err != nil {
615			return nil, err
616		}
617		return buildTransferView(cp), nil
618	}
619	
620	// DestroyInput 是销毁样品全部剩余量的入参；销毁不接受部分销毁。
621	type DestroyInput struct {
622		// SampleID 为样品编号。
623		SampleID string
624		// Operator 为操作人，去空白后必须与样品当前持有人一致。
625		Operator string
626		// Location 为销毁所在地点，去空白后必须与样品当前地点一致。
627		Location string
628		// At 为销毁时间，不能为零，也不能早于该样品任何已有保管历史的时间。
629		At time.Time
630		// Reason 为销毁原因，去空白后非空。
631		Reason string
632	}
633	
634	// Destroy 销毁该编号样品当时的全部剩余量（不接受部分销毁）。成功后
635	// 剩余量变为 0.000，初始量、来源关系、子样列表与原有保管历史保留，
636	// 持有人和地点保留为销毁前的最后记录，并在保管历史末尾追加一次销毁
637	// 事件；返回该样品的最新查询结果。
638	//
639	// 已销毁样品重复提交完全相同的操作人、地点、时间和原因时，返回原销毁
640	// 结果且不再追加历史；文本按去首尾空白后的内容比较，时间按实际时刻
641	// 比较。任一项不同则返回 ErrConflict，不覆盖原记录。
642	func (s *Store) Destroy(in DestroyInput) (*Sample, error) {
643		s.mu.Lock()
644		defer s.mu.Unlock()
645	
646		sampleID, err := trimRequired("样品编号", in.SampleID)
647		if err != nil {
648			return nil, err
649		}
650		operator, err := trimRequired("操作人", in.Operator)
651		if err != nil {
652			return nil, err
653		}
654		location, err := trimRequired("所在地点", in.Location)
655		if err != nil {
656			return nil, err
657		}
658		reason, err := trimRequired("销毁原因", in.Reason)
659		if err != nil {
660			return nil, err
661		}
662		if in.At.IsZero() {
663			return nil, fmt.Errorf("%w: 销毁时间不能为空", ErrInvalid)
664		}
665		at := in.At.UTC()
666	
667		rec, ok := s.data.Samples[sampleID]
668		if !ok {
669			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
670		}
671	
672		// 已销毁：只接受与首次销毁完全相同的重复提交，原样返回且不再追加历史。
673		if rec.Destroyed != nil {
674			if !sameDestruction(rec.Destroyed, operator, location, at, reason) {
675				return nil, fmt.Errorf("%w: 样品 %q 已销毁，本次销毁信息与原销毁记录不一致",
676					ErrConflict, sampleID)
677			}
678			return buildSampleView(rec, s.data), nil
679		}
680	
681		// 未销毁样品的状态冲突（持有人/地点不匹配按入参语义归入冲突类）。
682		if operator != rec.Holder {
683			return nil, fmt.Errorf("%w: 操作人 %q 与样品 %q 当前持有人 %q 不一致",
684				ErrConflict, operator, sampleID, rec.Holder)
685		}
686		if location != rec.Location {
687			return nil, fmt.Errorf("%w: 销毁地点 %q 与样品 %q 当前地点 %q 不一致",
688				ErrConflict, location, sampleID, rec.Location)
689		}
690		if rec.PendingID != "" {
691			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能销毁",
692				ErrConflict, sampleID, rec.PendingID)
693		}
694		if rec.Remaining == 0 {
695			return nil, fmt.Errorf("%w: 样品 %q 剩余量已为零且未销毁，不能再销毁",
696				ErrConflict, sampleID)
697		}
698		for _, h := range rec.History {
699			if at.Before(h.Time) {
700				return nil, fmt.Errorf("%w: 销毁时间不能早于样品 %q 已有保管历史的时间 %s",
701					ErrInvalid, sampleID, h.Time.Format(time.RFC3339))
702			}
703		}
704	
705		candidate := s.data.deepCopy()
706		cp := candidate.Samples[sampleID]
707		destroyedQty := cp.Remaining
708		cp.Remaining = 0
709		cp.Destroyed = &destructionRecord{
710			Operator: operator,
711			Location: location,
712			At:       at,
713			Reason:   reason,
714			Qty:      destroyedQty,
715		}
716		// 持有人和地点保留为销毁前的最后记录，仅在历史末尾追加销毁事件。
717		cp.History = append(cp.History, historyRecord{
718			Kind:     "destroy",
719			Time:     at,
720			Holder:   operator,
721			Location: location,
722			Detail:   fmt.Sprintf("销毁全部剩余量 %s 毫升，原因：%s", formatUnits(destroyedQty), reason),
723		})
724	
725		if err := s.commit(candidate); err != nil {
726			return nil, err
727		}
728		return buildSampleView(cp, candidate), nil
729	}
730	
731	// sameDestruction 判断本次销毁请求与已有销毁记录是否完全相同。
732	// 文本字段均已去首尾空白，时间按实际时刻（Equal）比较。
733	func sameDestruction(d *destructionRecord, operator, location string, at time.Time, reason string) bool {
734		return d.Operator == operator &&
735			d.Location == location &&
736			d.At.Equal(at) &&
737			d.Reason == reason
738	}
739	
740	// GetSample 按样品编号查询：返回来源关系、初始量/剩余量、当前持有人和
741	// 地点、直接子样、按发生顺序排列的保管历史，以及待确认交接详情。
742	// 样品不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
743	func (s *Store) GetSample(id string) (*Sample, error) {
744		s.mu.Lock()
745		defer s.mu.Unlock()
746	
747		sampleID, err := trimRequired("样品编号", id)
748		if err != nil {
749			return nil, err
750		}
751		rec, ok := s.data.Samples[sampleID]
752		if !ok {
753			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
754		}
755		return buildSampleView(rec, s.data), nil
756	}
757	
758	// GetTransfer 按交接编号查询交接详情（待确认或已确认）。
759	// 交接不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
760	func (s *Store) GetTransfer(id string) (*TransferView, error) {
761		s.mu.Lock()
762		defer s.mu.Unlock()
763	
764		transferID, err := trimRequired("交接编号", id)
765		if err != nil {
766			return nil, err
767		}
768		rec, ok := s.data.Transfers[transferID]
769		if !ok {
770			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
771		}
772		return buildTransferView(rec), nil
773	}
774	
775	// buildSampleView 把内部样品记录转换为对外视图，数量统一格式化为三位小数。
776	func buildSampleView(r *sampleRecord, l *ledger) *Sample {
777		children := append([]string{}, r.Children...)
778		history := make([]History, 0, len(r.History))
779		for _, h := range r.History {
780			history = append(history, History{
781				Kind:     h.Kind,
782				Time:     h.Time,
783				Holder:   h.Holder,
784				Location: h.Location,
785				Detail:   h.Detail,
786			})
787		}
788		v := &Sample{
789			ID:         r.ID,
790			ParentID:   r.ParentID,
791			InitialQty: formatUnits(r.Initial),
792			Remaining:  formatUnits(r.Remaining),
793			Holder:     r.Holder,
794			Location:   r.Location,
795			Children:   children,
796			History:    history,
797		}
798		if r.PendingID != "" {
799			if t, ok := l.Transfers[r.PendingID]; ok {
800				v.PendingTransfer = buildTransferView(t)
801			}
802		}
803		if r.Destroyed != nil {
804			v.Destruction = &Destruction{
805				Operator: r.Destroyed.Operator,
806				Location: r.Destroyed.Location,
807				At:       r.Destroyed.At,
808				Reason:   r.Destroyed.Reason,
809				Qty:      formatUnits(r.Destroyed.Qty),
810			}
811		}
812		return v
813	}
814	
815	// buildTransferView 把内部交接记录转换为对外视图。
816	func buildTransferView(r *transferRecord) *TransferView {
817		v := &TransferView{
818			TransferID:   r.ID,
819			SampleID:     r.SampleID,
820			FromHolder:   r.FromHolder,
821			FromLocation: r.FromLocation,
822			ToHolder:     r.ToHolder,
823			ToLocation:   r.ToLocation,
824			Qty:          formatUnits(r.Qty),
825			HandedOverAt: r.HandedOverAt,
826			Confirmed:    r.Confirmed,
827			ConfirmedBy:  r.ConfirmedBy,
828		}
829		if r.ReceivedAt != nil {
830			rx := *r.ReceivedAt
831			v.ReceivedAt = &rx
832			v.ConfirmedAt = r.ToLocation
833		}
834		return v
835	}
